  u_core.jtag_DRV_TDO(jtag_DRV_TDO);
  u_core.jtag_TMS_out(jtag_TMS_out);
  u_core.jtag_DRV_TMS(jtag_DRV_TMS);
  u_core.jtag_BK_TMS(jtag_BK_TMS);
  u_core.jtag_dwen(jtag_dwen);
  u_core.jtag_dwbypass(jtag_dwbypass);
  u_core.i_dbg_stop(i_dbg_stop);
  u_core.override_dm_sleep(override_dm_sleep);
  u_core.hart_halted(hart_halted);
  u_core.dbg_stoptime(dbg_stoptime);
  u_core.sysrstreq(sysrstreq);
  u_core.mtime_toggle_a(mtime_toggle_a);
  u_core.dbg_toggle_a(dbg_toggle_a);
  u_core.dcache_disable_init(dcache_disable_init);
  u_core.icache_disable_init(icache_disable_init);
  u_core.mmu_tlb_disable_init(mmu_tlb_disable_init);
  u_core.trace_ivalid(i0_trace_ivalid);
  u_core.trace_iexception(i0_trace_iexception);
  u_core.trace_interrupt(i0_trace_interrupt);
  u_core.trace_cause(__bridge_u_core_trace_cause);
  u_core.trace_tval(__bridge_u_core_trace_tval);
  u_core.trace_iaddr(__bridge_u_core_trace_iaddr);
  u_core.trace_instr(__bridge_u_core_trace_instr);
  u_core.trace_priv(__bridge_u_core_trace_priv);
  u_core.trace_bjp_taken(i0_trace_bjp_taken);
  u_core.trace_dmode(i0_trace_dmode);
  u_core.trace_cmt_ena(i0_trace_cmt_ena);
  u_core.nmi(nmi);
  u_core.irq_i(__bridge_u_core_irq_i);
